import{_ as a,o,c as r,a3 as e}from"./chunks/framework.DotqndlA.js";const l="/ems_simulate/assets/dlt645-add.BI-eYVGn.png",i="/ems_simulate/assets/dlt645-operation.EH6CDhGw.png",b=JSON.parse('{"title":"DL/T 645-2007 操作指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/dlt645/operation.md","filePath":"guide/protocols/dlt645/operation.md","lastUpdated":1786981506000}'),d={name:"guide/protocols/dlt645/operation.md"};function n(s,t,h,c,u,p){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="dl-t-645-2007-操作指南" tabindex="-1">DL/T 645-2007 操作指南 <a class="header-anchor" href="#dl-t-645-2007-操作指南" aria-label="Permalink to &quot;DL/T 645-2007 操作指南&quot;">​</a></h1><h2 id="一、前置条件" tabindex="-1">一、前置条件 <a class="header-anchor" href="#一、前置条件" aria-label="Permalink to &quot;一、前置条件&quot;">​</a></h2><ul><li>已安装并启动 EMS Simulate；</li><li><strong>服务端模拟</strong>：本机即可完成全流程演示；</li><li><strong>客户端模式</strong>：需要一台真实电表（或本软件再模拟一台服务端）。</li></ul><h2 id="二、服务端模式-模拟电能表" tabindex="-1">二、服务端模式（模拟电能表） <a class="header-anchor" href="#二、服务端模式-模拟电能表" aria-label="Permalink to &quot;二、服务端模式（模拟电能表）&quot;">​</a></h2><p><strong>目标</strong>：模拟一台 DL/T645 电能表，响应主站抄表。</p><h3 id="步骤-1-添加设备" tabindex="-1">步骤 1：添加设备 <a class="header-anchor" href="#步骤-1-添加设备" aria-label="Permalink to &quot;步骤 1：添加设备&quot;">​</a></h3><ol><li>点击&quot;<strong>添加设备</strong>&quot;；</li><li>填写设备名称（如 <code>模拟电能表</code>）；</li><li>协议选择 <strong>DL/T 645-2007</strong>；</li><li>连接方式选择 <strong>串口从站</strong>（RS-485）或 <strong>TCP 服务端</strong>；</li><li>配置串口参数（串口号、波特率默认 2400/9600、数据位 8、校验）或 TCP 端口（默认 8899），保存。</li></ol><h3 id="步骤-2-选择点表模式" tabindex="-1">步骤 2：选择点表模式 <a class="header-anchor" href="#步骤-2-选择点表模式" aria-label="Permalink to &quot;步骤 2：选择点表模式&quot;">​</a></h3><p>进入设备详情，DL/T645 设备提供两种模式（可切换）：</p><ul><li><strong>标准点表</strong>：点击后自动从内置 dlt645 标准数据项库生成完整点表，覆盖电能量、需量、电压、电流、功率、功率因数等常用数据项；</li><li><strong>导入点表</strong>：上传 Excel 点表，按自定义数据项导入。</li></ul><p><img src="'+l+'" alt=""></p><h3 id="步骤-3-启动设备" tabindex="-1">步骤 3：启动设备 <a class="header-anchor" href="#步骤-3-启动设备" aria-label="Permalink to &quot;步骤 3：启动设备&quot;">​</a></h3><p>点击&quot;<strong>开启设备</strong>&quot;，电表开始监听并响应抄表请求。</p><h3 id="步骤-4-客户端读取验证" tabindex="-1">步骤 4：客户端读取验证 <a class="header-anchor" href="#步骤-4-客户端读取验证" aria-label="Permalink to &quot;步骤 4：客户端读取验证&quot;">​</a></h3><ol><li>添加 DL/T645 <strong>客户端</strong>设备（串口或 TCP 指向本机）；</li><li>启动后点击&quot;<strong>读取</strong>&quot;，验证： <ul><li>数据标识解析是否正确（如 <code>00010000</code> → 正向有功总电能）；</li><li>返回值与系数换算后的真实值（电能度数、电压值等）。</li></ul></li></ol><p><img src="'+i+'" alt=""></p><h2 id="三、客户端模式-抄读真实电表" tabindex="-1">三、客户端模式（抄读真实电表） <a class="header-anchor" href="#三、客户端模式-抄读真实电表" aria-label="Permalink to &quot;三、客户端模式（抄读真实电表）&quot;">​</a></h2><ol><li>添加设备时连接方式选择 <strong>客户端（主站）</strong>，配置串口或 TCP 参数与表地址；</li><li>添加需要抄读的数据项测点（数据标识与真实电表一致）；</li><li>启动后点击&quot;读取&quot;，观察返回数据与系数换算结果；</li><li>支持批量抄读常用数据项。</li></ol><h2 id="四、协议参数详解" tabindex="-1">四、协议参数详解 <a class="header-anchor" href="#四、协议参数详解" aria-label="Permalink to &quot;四、协议参数详解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>命令超时</td><td>3000ms</td><td>单条抄表命令等待响应的超时时间</td></tr><tr><td>波特率</td><td>2400 / 9600</td><td>串口通信速率（与电表一致）</td></tr><tr><td>表地址</td><td>6 字节 BCD</td><td>电表地址（可自动识别或手动设置）</td></tr></tbody></table><h2 id="五、常见问题" tabindex="-1">五、常见问题 <a class="header-anchor" href="#五、常见问题" aria-label="Permalink to &quot;五、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>排查建议</th></tr></thead><tbody><tr><td>抄表超时</td><td>检查串口参数（波特率/校验位）、表地址、接线</td></tr><tr><td>数据标识解析错误</td><td>确认数据标识与电表型号的数据项定义一致</td></tr><tr><td>返回值偏差</td><td>检查乘法/加法系数与数据项倍率</td></tr><tr><td>TCP 模式连不上</td><td>确认端口（默认 8899）与 IP</td></tr></tbody></table><blockquote><p>📄 报文如何解析见 <a href="./packet-view.html">DL/T645 报文查看</a>。</p></blockquote>',23)])])}const m=a(d,[["render",n]]);export{b as __pageData,m as default};
